/**
 * Story 449 (DLR #355): keeps the screen on while a drill session runs, so the screen lock cannot hide the
 * page mid-session. Chrome drops the lock whenever the page is hidden; back to visible, while still held,
 * it is requested again. A refused request goes to `onError` and the drill runs on.
 */
export class DrillWakeLock {
    private readonly onError: (err: unknown) => void;
    private readonly wakeLock: WakeLock;
    private readonly doc: Document;
    private sentinel: WakeLockSentinel | null = null;
    private held = false;

    constructor(onError: (err: unknown) => void, wakeLock: WakeLock = navigator.wakeLock, doc: Document = document) {
        this.onError = onError;
        this.wakeLock = wakeLock;
        this.doc = doc;
    }

    async hold(): Promise<void> {
        this.held = true;
        this.doc.addEventListener('visibilitychange', this.onVisibilityChange);
        await this.request();
    }

    async release(): Promise<void> {
        this.held = false;
        this.doc.removeEventListener('visibilitychange', this.onVisibilityChange);
        const sentinel = this.sentinel;
        this.sentinel = null;
        if (sentinel && !sentinel.released) await sentinel.release();
    }

    private readonly onVisibilityChange = (): void => {
        if (this.held && this.doc.visibilityState === 'visible' && (this.sentinel?.released ?? true)) void this.request();
    };

    private async request(): Promise<void> {
        try {
            const sentinel = await this.wakeLock.request('screen');
            if (this.held) this.sentinel = sentinel;
            else await sentinel.release(); // released while the request was pending
        } catch (err) {
            this.onError(err);
        }
    }
}
